<?php
require_once __DIR__.'/invoice-common.php';
$invoiceId=caja_id($_GET,'id_factura');
try{$invoice=caja_invoice($invoiceId);$totals=caja_invoice_totals($invoiceId);}catch(InvalidArgumentException $error){caja_fail($error->getMessage(),404);}
$centre=(int)$invoice['invoice_centre'];$period=caja_period($centre);
$rows=caja_rows("SELECT p.*,CONCAT_WS(' ',u.Nombre,u.Apellido1,u.Apellido2) AS empleado FROM pagos_a_cuenta p LEFT JOIN usuarios u ON u.id_usuario=p.anotado_por WHERE p.id_factura=? ORDER BY p.fecha_pago DESC,p.hora_pago DESC,p.id_pago DESC",'i',[$invoiceId]);
$periods=[$centre=>$period];foreach($rows as $row)if(!isset($periods[(int)$row['id_centro']]))$periods[(int)$row['id_centro']]=caja_period((int)$row['id_centro']);
$refund=$totals['remaining']<0;$label=trim((string)$invoice['serie'].'-'.(string)$invoice['num_factura'],'-');
caja_header('Cobros de la factura '.$label);
?>
<p class="caja-subtitle"><?=app_escape(trim((string)$invoice['alumno'])?:'Alumno externo')?> &middot; Emitida el <?=caja_date($invoice['fecha_emision'])?></p>
<div class="caja-stats"><article class="caja-stat"><span>Total factura</span><strong><?=caja_money($totals['total'])?></strong></article><article class="caja-stat"><span>Cobros menos devoluciones</span><strong><?=caja_money($totals['paid'])?></strong></article><article class="caja-stat highlight"><span><?=$refund?'Pendiente de devolver':'Pendiente de cobro'?></span><strong><?=caja_money(abs($totals['remaining']))?></strong></article><article class="caja-stat"><span>Estado</span><strong style="font-size:22px"><?=$totals['remaining']===0?'Saldada':($refund?'Devoluci&oacute;n':'Pendiente')?></strong><small><?=count($rows)?> movimientos registrados</small></article></div>
<?php if($totals['remaining']!==0){ ?><section class="caja-card caja-form"><h2><?=$refund?'Registrar una devoluci&oacute;n':'Registrar un cobro'?></h2><form method="post" action="/facturacion/pagos_a_cuenta1.php" data-confirm="&iquest;Guardar este movimiento de la factura?"><input type="hidden" name="id_factura" value="<?=$invoiceId?>"><input type="hidden" name="caja_token" value="<?=caja_token('invoice_pay_'.$invoiceId,$centre,$period['previous_id'])?>"><div class="caja-form-grid"><label>Fecha del movimiento<input type="date" name="fecha_pago" value="<?=date('Y-m-d')?>" max="<?=date('Y-m-d')?>" required></label><label>Importe (&euro;)<input type="text" name="importe_pago" inputmode="decimal" value="<?=number_format(abs($totals['remaining'])/100,2,',','')?>" maxlength="12" required></label></div><label>Forma de pago<select name="forma_pago"><?php foreach(caja_methods() as $id=>$method){ ?><option value="<?=$id?>"><?=app_escape($method)?></option><?php } ?></select></label><label>Observaciones<textarea name="observaciones_pago" maxlength="2000" placeholder="Referencia del pago o motivo de la devoluci&oacute;n"></textarea></label><p class="caja-note">El movimiento se registrar&aacute; en la caja activa. Los cobros de cajas cerradas se conservan para mantener el historial.</p><div class="caja-actions"><button class="primary" type="submit"><?=$refund?'Guardar devoluci&oacute;n':'Guardar cobro'?></button><a class="caja-button" href="/caja/listado_caja.php?id_centro_caja=<?=$centre?>">Volver a caja</a></div></form></section><?php } ?>
<section class="caja-card"><h2>Movimientos de esta factura</h2><div class="caja-rotate">Gira el dispositivo o desliza para consultar todos los datos.<button type="button" data-landscape>Ver en horizontal</button></div><div class="caja-table-wrap"><table class="caja-table"><thead><tr><th>Fecha</th><th>Forma de pago</th><th>Observaciones</th><th>Registrado por</th><th class="number">Importe</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $row){$amount=(int)round((float)$row['importe_pago']*100)*(int)$row['signo'];$open=caja_payment_is_open($row,$periods[(int)$row['id_centro']])&&security_owned_centre((int)$row['id_centro']); ?><tr><td><?=caja_date($row['fecha_pago'])?><small><?=app_escape(substr((string)$row['hora_pago'],0,5))?></small></td><td><?=app_escape(caja_method($row['forma_pago']))?></td><td><?=nl2br(app_escape($row['observaciones_pago']))?><small><?=$open?'Caja abierta':'Caja cerrada: movimiento protegido'?></small></td><td><?=app_escape(trim((string)$row['empleado'])?:'No disponible')?></td><td class="number <?=$amount<0?'caja-negative':'caja-positive'?>"><?=caja_money($amount)?></td><td><a class="caja-button" href="/pdf/recibos.php?id_factura=<?=$invoiceId?>&amp;id_pago=<?=(int)$row['id_pago']?>" target="_blank" rel="noopener">Ver recibo</a><?php if($open){ ?><form method="post" class="caja-inline-form" action="/facturacion/eliminar_pago_a_cuenta.php" data-confirm="&iquest;Eliminar este movimiento de la factura y de la caja abierta?"><input type="hidden" name="id_factura" value="<?=$invoiceId?>"><input type="hidden" name="id_pago" value="<?=(int)$row['id_pago']?>"><button class="danger" type="submit">Eliminar</button></form><?php } ?></td></tr><?php }if(!$rows){ ?><tr><td colspan="6" class="caja-empty">Esta factura todav&iacute;a no tiene cobros.</td></tr><?php } ?></tbody></table></div></section><p><a href="/caja/listado_caja.php?id_centro_caja=<?=$centre?>">Volver a caja</a></p>
<?php caja_footer(); ?>
